from datetime import datetime, timedelta

db_path = 'foreign_ownership.db'
conn = sqlite3.connect(db_path)

def calculate_date(date_str, days):
    date_obj = datetime.strptime(date_str, '%Y-%m-%d')
    
    new_date_obj = date_obj + timedelta(days=days)
    new_date_str = new_date_obj.strftime('%Y-%m-%d')
    
    return new_date_str

def calculate_market_cap_weight(df):
    df['Market Cap'] = df['Close'] * df['No. of listed shares']
    df['Market Cap Weight'] = df.groupby('date')['Market Cap'].transform(lambda x: x / x.sum())
    return df

def calculate_market_cap_weight_industry(df):
    df['Market Cap'] = df['Close'] * df['No. of listed shares']
    df['Market Cap Weight'] = df.groupby(['date', 'Industry'])['Market Cap'].transform(lambda x: x / x.sum())
    return df

def calculate_market_cap_weight_KOSPI200(df, const):
    df_kospi200 = df[df['Issue code'].isin(const)].copy()
    df_kospi200['Market Cap'] = df_kospi200['Close'] * df_kospi200['No. of listed shares']
    df_kospi200['Market Cap Weight'] = df_kospi200.groupby('date')['Market Cap'].transform(lambda x: x / x.sum())
    return df_kospi200

def policy_change_analysis(conn, date_str, before_days, after_days, const):
    before = calculate_date(date_str, before_days)
    after = calculate_date(date_str, after_days)

    query = f'SELECT "date", "Issue name", "Close", "Issue code", "No. of listed shares", "No. of shares of foreign ownership", "Foreign ownership ratio", "Foreign ownership limit quantity", "Exhaustion rate", "Industry" FROM foreign_ownership WHERE "date" <= "{after}" AND "date" >= "{before}" AND not("Industry" is NULL)'
    df = pd.read_sql_query(query, conn)
    df["Close"] = df["Close"].str.replace(',','').astype(float)
    df["No. of listed shares"] = df["No. of listed shares"].str.replace(',','').astype(int)
    market = calculate_market_cap_weight(df)
    industry = calculate_market_cap_weight_industry(df)
    KOSPI200 = calculate_market_cap_weight_KOSPI200(df, const)

